    [5, 5, 5, 5, 7, 5, 5, 5, 5, 7, 5, 5, 4, 4, 7, 4, 5, 5, 5]
]

panels_count = [[0 for _ in range(4)] for _ in range(2)]

for r in range(11):
    for c in range(19):
        if demo_input[r][c] == 4:
            # Determine panel
            if r < 5:
                panel_r = 0
            else:
                panel_r = 1

            # Determine panel column
            if c < 5:
                panel_c = 0
            elif c < 10:
                panel_c = 1
            elif c < 15:
                panel_c = 2
            else:
                panel_c = 3

            panels_count[panel_r][panel_c] += 1

print("Demo panel counts of 4s:")
print(panels_count)

# Output mapping: panels with count=2 get "1", panels with count=1 get "5"
output = [[5]*4 for _ in range(2)]
for r in range(2):
    for c in range(4):
        if panels_count[r][c] == 2:
            output[r][c] = 1

print("\nPredicted output with count=2->1, count=1->5:")
print(output)
